# von_bertalanffy_length_at_age ----
## Setup ----
# The classic von Bertalanffy curve with Linf = 800, K = 0.18 and
# a0 = -1.36, as in the test operating model.
classic_length_at_age <- function(age) 800 * (1 - exp(-0.18 * (age + 1.36)))
ages <- 1:12

## IO correctness ----
test_that("`von_bertalanffy_length_at_age()` works with correct inputs", {
  schnute_length_at_age <- FIMS:::von_bertalanffy_length_at_age(
    ages, classic_length_at_age(1), classic_length_at_age(12), 0.18, 1, 12
  )
  # FIMS's smooth guard on the denominator shifts lengths by about 1e-5
  # relative, so the match is close but not exact.
  #' @description Test that the Schnute form of `von_bertalanffy_length_at_age()` equals the classic von Bertalanffy curve when given its lengths at the 2 reference ages.
  expect_equal(
    object = schnute_length_at_age,
    expected = classic_length_at_age(ages),
    tolerance = 1e-4
  )
})

## Edge handling ----
test_that("`von_bertalanffy_length_at_age()` returns correct outputs for edge cases", {
  # Ages below the young reference age grow linearly from length 0 at age 0
  # to L1 at the young reference age, here L1 = 100 at age 2.
  younger_length_at_age <- FIMS:::von_bertalanffy_length_at_age(
    c(0, 0.5, 1, 2), 100, 500, 0.2, 2, 10
  )
  #' @description Test that `von_bertalanffy_length_at_age()` gives L1 times age / a1 below the young reference age, so 0, 25 and 50 at ages 0, 0.5 and 1 with L1 = 100 and a1 = 2.
  expect_equal(
    object = younger_length_at_age[1:3],
    expected = c(0, 25, 50)
  )
  #' @description Test that `von_bertalanffy_length_at_age()` gives L1 at the young reference age, where the linear segment meets the curve.
  expect_equal(
    object = younger_length_at_age[4],
    expected = 100
  )
  #' @description Test that `von_bertalanffy_length_at_age()` gives length 0 at ages below 0.
  expect_equal(
    object = FIMS:::von_bertalanffy_length_at_age(-1, 100, 500, 0.2, 2, 10),
    expected = 0
  )
})

## Error handling ----
